frappe.ui.form.on('Sales Order', {
    refresh: function(frm) {
        // 1. Target the specific grid wrapper for "items"
        const grid = frm.fields_dict.items.grid;
        
        // 2. Use Event Delegation on the wrapper
        // This listens for any 'keydown' on a textarea inside the 'description' column
        $(grid.wrapper).off('keydown').on('keydown', '.grid-row [data-fieldname="description"] textarea', function(e) {
            
            // Check for TAB key (and ignore Shift+Tab)
            if (e.key === 'Tab' && !e.shiftKey) {
                e.preventDefault(); 
                e.stopImmediatePropagation(); // Kills the "space" insertion

                // Get the current row details from the DOM
                let $row = $(e.target).closest('.grid-row');
                let cdn = $row.attr('data-name');
                let index = grid.get_row_index(cdn);

                // Check if we are at the last row
                if (index + 1 < grid.grid_rows.length) {
                    // --- CASE 1: Next Row Exists ---
                    // Focus the "Item Code" of the NEXT row
                    // We trigger a click on the static div to turn it into an input
                    let next_row_cdn = grid.grid_rows[index + 1].doc.name;
                    let $next_cell = $(grid.wrapper).find(`.grid-row[data-name="${next_row_cdn}"] [data-fieldname="item_code"]`);
                    
                    if ($next_cell.length) {
                         $next_cell.click(); // This activates the cell
                    }
                } else {
                    // --- CASE 2: Add New Row ---
                    // Add a new row programmatically
                    let new_row = frm.add_child('items');
                    frm.refresh_field('items');

                    // Wait for the grid to redraw the new row
                    setTimeout(() => {
                        // Find the new row's Item Code cell and click it to focus
                        let $new_cell = $(grid.wrapper).find(`.grid-row[data-name="${new_row.name}"] [data-fieldname="item_code"]`);
                        if ($new_cell.length) {
                            $new_cell.click();
                        }
                    }, 200); // Small delay for DOM refresh
                }
            }
        });
    }
});

