                               value="${row.qty || 0}">
                    </div>

                    <div>
                        <i class="fa fa-trash text-danger delete-item-btn"
                           data-name="${row.name}"
                           style="cursor:pointer;"></i>
                    </div>

                </div>

                <!-- NOTES -->
                <div>
                    <small class="toggle-notes"
                           data-name="${row.name}"
                           style="color:var(--text-muted); cursor:pointer;">
                        Notes
                    </small>

                    <textarea id="notes_${row.name}"
                              class="form-control input-xs"
