                              style="display:none; margin-top:2px;">
                        ${row.additional_notes || ""}
                    </textarea>
                </div>

            </div>
        `);

        list_container.append(card);

        create_item_link_field(frm, row, card);
        bind_card_events(frm, row, card);
    });

    // ADD ROW
    $("#add_custom_item_btn").off("click").on("click", () => {
        frm.add_child("items");
        frm.refresh();
    });

    // DELETE ROW
    list_container.on("click", ".delete-item-btn", function () {
