function create_item_link_field(frm, row, card) {

    const parent = card.find(`#item_link_${row.name}`);
    parent.empty();

    const field = frappe.ui.form.make_control({
        df: {
            fieldtype: "Link",
            fieldname: "item_code",
            options: "Item",
            placeholder: "Item",
            only_input: true,
            change: async function () {

                const val = this.get_value();
                frappe.model.set_value(row.doctype, row.name, "item_code", val);

                if (val) {
                    const r = await frappe.db.get_value(
                        "Item",
                        val,
                        ["item_name", "stock_uom"]
                    );

                    if (r.message) {
                        frappe.model.set_value(row.doctype, row.name, {
                            item_name: r.message.item_name,
                            uom: r.message.stock_uom
                        });
                    }
                }
            }
        },
        parent,
        doc: row,
        render_input: true
    });

    if (field?.set_value) {
        field.set_value(row.item_code || "", true, false);
    }
}


