function bind_card_events(frm, row, card) {

    // QTY
    card.find(`#qty_${row.name}`)
        .off("change")
        .on("change", function () {
            frappe.model.set_value(
                row.doctype,
                row.name,
                "qty",
                flt($(this).val())
            );
        });

    // NOTES
    card.find(`#notes_${row.name}`)
        .off("change")
        .on("change", function () {
            frappe.model.set_value(
                row.doctype,
                row.name,
                "additional_notes",
                $(this).val()
            );
        });
}

