function create_link_field(frm, row, card) {
    let parent_div = card.find(`#item_link_${row.name}`);
    if(!parent_div.length) return;
    parent_div.empty();

    let field = frappe.ui.form.make_control({
        df: {
            fieldtype: "Link",
            options: "Item",
            fieldname: "item_code",
            placeholder: "",
            only_input: true,
            get_query: () => { return {}; },
            change: async function() {
                let val = this.get_value();
                frappe.model.set_value(row.doctype, row.name, 'item_code', val);
                if (val) {
                    let r = await frappe.db.get_value("Item", val, ["item_name", "description", "stock_uom"]);
                    if(r && r.message) {
                        frappe.model.set_value(row.doctype, row.name, {
                            item_name: r.message.item_name,
                            description: r.message.description,
                            uom: r.message.stock_uom
                        });
                        // Fast UI Update
                        card.find(`#desc_${row.name}`).val(r.message.description);
                        card.find(`.uom-badge`).text(r.message.stock_uom);
                        let helper_text = (r.message.item_name !== val) ? r.message.item_name : '&nbsp;';
                        card.find(`.item-helper`).html(helper_text);
                    }
                }
            }
        },
        parent: parent_div,
        doc: row,
        render_input: true
    });

    if (field) {
        field.refresh(); 
        if (field.set_value) field.set_value(row.item_code || "", true, false);
    }
}

/**
 * Binds row events (Qty change, Description focus)
 */
function bind_row_events(frm, row, card) {
    // Qty Sync
    card.find(`#qty_${row.name}`).on("change", function() {
        frappe.model.set_value(row.doctype, row.name, "qty", flt($(this).val()));
    });
    
    // Description Sync
    card.find(`#desc_${row.name}`).on("change", function() {
        frappe.model.set_value(row.doctype, row.name, "description", $(this).val());
    });
    
    // Description Expand Animation
    card.find(`#desc_${row.name}`).on("focus", function() {
        $(this).css("height", "80px"); // Expand Vertically
    }).on("blur", function() {
        $(this).css("height", "32px"); // Shrink back
        $(this).scrollTop(0);
    });
}

