            // Conditional Coloring
            if (details === "Not Delivered") {
                statusColor = "#e24c4c"; // Red
            } else if (details === "Partly Delivered") {
                statusColor = "#f59f00"; // Orange
            } else if (details === "Fully Delivered") {
                statusColor = "#2f9d58"; // Green (Optional, looks nice)
            }

            // Create HTML with the dynamic color
            const detailsHtml = details 
                ? `<div class="list-row-details" style="color: ${statusColor}">${details}</div>` 
                : "";

            return `
                <div class="list-row-container" tabindex="1">
                    <div class="level list-row">
                        <div class="level-left ellipsis">
                            ${left}
                        </div>
                        <div class="level-right text-muted ellipsis">
                            ${right}
                        </div>
                    </div>
                    ${detailsHtml}
                </div>
            `;
        }
        return super.get_list_row_html_skeleton(left, right);
    }

    get_list_row_html(doc) {
        return this.get_list_row_html_skeleton(
            this.get_left_html(doc),
            this.get_right_html(doc),
            doc.delivery_status
        );
