window.make_dn_from_so = function(event, so_name) {
    // Prevent the click from bubbling up to the row
    if (event) {
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
    }

    // Visual feedback
    let btn = event.target;
    if (btn) {
        btn.disabled = true;
        btn.innerText = "...";
    }

    // API Call
    frappe.call({
        method: "erpnext.selling.doctype.sales_order.sales_order.make_delivery_note",
        args: { source_name: so_name },
        freeze: true,
        freeze_message: "Creating Delivery Note...",
        callback: function(r) {
            if (btn) {
                btn.disabled = false;
                btn.innerText = "DN";
            }
            if (!r.exc && r.message) {
                frappe.model.sync(r.message);
                frappe.set_route("Form", "Delivery Note", r.message.name);
            }
        },
        error: function(r) {
            if (btn) {
                btn.disabled = false;
                btn.innerText = "DN";
            }
        }
    });
    return false;
};

