            if ($('#custom-so-list-css').length === 0) {
                $('<style id="custom-so-list-css">')
                    .prop('type', 'text/css')
                    .html(`
                        /* 1. Disable Filter-Click on ALL columns */
                        /* This forces the click to fall through to the Row, opening the Form */
                        .list-row .list-row-col { 
                            pointer-events: none !important; 
                        }

                        /* 2. Re-enable interactions for the Checkbox (Selection) */
                        .list-row .list-row-checkbox, 
                        .list-row .checkbox { 
                            pointer-events: auto !important; 
                            cursor: pointer !important;
                        }

                        /* 3. Re-enable interactions for your Custom Button */
                        .so-create-dn { 
                            pointer-events: auto !important; 
                            cursor: pointer !important;
                            z-index: 999;
                        }

                        /* 4. Hide Heart/Like Button */
                        .list-row-like { display: none !important; }

                        /* 5. Mobile Tag Logic */
                        @media (min-width: 768px) {
                            .mobile-only-tag { display: none !important; }
                        }
                        @media (max-width: 767px) {
                            .mobile-only-tag { display: block !important; }
                            .so-create-dn { display: none !important; }
                        }
                    `)
                    .appendTo('head');
            }

            // --- B. Dynamic Logic (Hide Status & Hide Checkboxes) ---
            this.update_dynamic_view();
        }
    }

    update_dynamic_view() {
        const filters = this.filter_area ? this.filter_area.get() : [];

        // --- Logic 1: Hide Status Column (If 'workflow_state' is 'Approved') ---
        const should_hide_status = filters.some(f => f[1] === 'workflow_state' && f[3] === 'Approved');
        const statusStyleId = 'dynamic-hide-status-col';
        const $statusStyle = $('#' + statusStyleId);

        if (should_hide_status) {
            if ($statusStyle.length === 0) {
                $('<style id="' + statusStyleId + '">')
                    .prop('type', 'text/css')
                    .html(`
                        .list-headers [data-fieldname="status"],
                        .list-headers [data-fieldname="workflow_state"],
                        .list-headers .list-item__content:contains("Status"),
                        .list-row [data-fieldname="status"],
                        .list-row [data-fieldname="workflow_state"] { 
                            display: none !important; 
                        }
                    `)
                    .appendTo('head');
            }
        } else {
            if ($statusStyle.length > 0) $statusStyle.remove();
        }

        // --- Logic 2: Hide Select Buttons (If more than 2 filters are active) ---
        const should_hide_select = filters.length > 2;
        const selectStyleId = 'dynamic-hide-select-btn';
        const $selectStyle = $('#' + selectStyleId);

        if (should_hide_select) {
            if ($selectStyle.length === 0) {
                $('<style id="' + selectStyleId + '">')
                    .prop('type', 'text/css')
                    .html(`
                        /* Hide Row Checkboxes */
                        .list-row-checkbox { display: none !important; }
                        
                        /* Hide Header Select-All Checkbox */
                        .list-check-all { display: none !important; }
                        .list-header-subject .checkbox { display: none !important; }

                        /* Adjust padding since checkbox is gone */
                        .list-row-col:first-child { padding-left: 15px !important; }
                    `)
                    .appendTo('head');
            }
        } else {
            if ($selectStyle.length > 0) $selectStyle.remove();
        }
    }

    get_list_row_html_skeleton(left = "", right = "", details = "") {
        if (this.doctype === "Sales Order") {
            let statusColor = "#8d99a6";
            if (details === "Not Delivered") statusColor = "#e24c4c";
            else if (details === "Partly Delivered") statusColor = "#f59f00";
            else if (details === "Fully Delivered") statusColor = "#2f9d58";

            const detailsHtml = details
                ? `<div class="list-row-details mobile-only-tag" style="color:${statusColor}">${details}</div>`
                : "";

            return `
                <div class="list-row-container" tabindex="1">
                    <div class="level list-row">
                        <div class="level-left ellipsis">${left}</div>
                        <div class="level-right ellipsis so-actions">${right}</div>
                    </div>
                    ${detailsHtml}
                </div>
            `;
        }
        return super.get_list_row_html_skeleton(left, right);
    }

    get_right_html(doc) {
        let standardHtml = super.get_right_html(doc);
        let buttonHtml = "";

        if (
            doc.docstatus === 1 &&
            doc.delivery_status !== "Fully Delivered" &&
            doc.status !== "Closed"
        ) {
            buttonHtml = `
                <button
                    class="btn btn-xs so-create-dn"
                    style="
                        margin-right: 15px;
                        z-index: 999; 
                        position: relative; 
                        background-color: #000; 
                        color: #fff; 
                        border: none;
                        pointer-events: auto;
                    "
                    onclick="window.make_dn_from_so(event, '${doc.name}')"
                    title="Create Delivery Note"
                >
                    CDN
                </button>
            `;
        }
        return buttonHtml + standardHtml;
    }

    get_list_row_html(doc) {
        return this.get_list_row_html_skeleton(
            this.get_left_html(doc),
            this.get_right_html(doc),
            doc.delivery_status
        );
    }
};

frappe.listview_settings['Sales Order'] = {
    refresh: function(listview) {
        // Wait a moment for the list to fully render
        setTimeout(() => {
            // 1. Get the current number of filters
            let filter_count = 0;
            if (listview.filter_area && listview.filter_area.get) {
                filter_count = listview.filter_area.get().length;
            }

            // 2. Logic: If more than 3 filters, hide buttons and change title
            if (filter_count > 2) {
                // Change Title
                listview.page.set_title('Delivery');
                
                // Hide the entire top-right action area (includes Refresh, Menu, List View switch)
                listview.page.wrapper.find('.page-actions').hide();
                
                // Specifically hide the "Add Sales Order" button (Primary Action)
                listview.page.wrapper.find('.btn-primary').hide();
            } 
            else {
                // Revert Title
                listview.page.set_title('Sales Order');
                
                // Show everything back
                listview.page.wrapper.find('.page-actions').show();
                listview.page.wrapper.find('.btn-primary').show();
            }
        }, 100); // 100ms delay to ensure elements exist
    }
};

frappe.listview_settings['Sales Order'] = {
    onload: function(listview) {
        $(document).on('page-change', function() {
            $('[id^="so-expand-"]').remove();
        });

        $('<style>')
            .text(`
                .list-row-col .btn-view-items { 
                    order: -1 !important; 
                    margin-right: 8px; 
                }
            `)
            .appendTo('head');
    },

    refresh: function(listview) {
        $('[id^="so-expand-"]').remove();
    },

    button: {
        show: function(doc) {
            return true;
        },

        get_label: function(doc) {
            return 'View Items';
        },

        get_description: function(doc) {
            return doc.name;
        },

        action: function(doc) {
            let safeId = 'so-expand-' + doc.name.replace(/[^a-zA-Z0-9]/g, '-');
            let $existing = $('#' + safeId);

            if ($existing.length) {
                $existing.slideUp(150, function() { $(this).remove(); });
                return;
            }

            frappe.call({
                method: 'frappe.client.get',
                args: { doctype: 'Sales Order', name: doc.name },

                callback: function(r) {
                    if (!r.message) return;

                    let items = r.message.items || [];

                    let rows = items.map(function(item, idx) {

                        let deliveredPct = item.qty > 0 
                            ? Math.round((item.delivered_qty / item.qty) * 100) 
                            : 0;

                        let barColor = deliveredPct === 100 
                            ? '#28a745' 
                            : deliveredPct > 0 
                                ? '#f0a500' 
                                : '#e0e0e0';

                        let statusColor = deliveredPct === 100 
                            ? '#28a745' 
                            : deliveredPct > 0 
                                ? '#f0a500' 
                                : '#888';

                        let statusLabel = deliveredPct === 100 
                            ? 'Delivered' 
                            : deliveredPct > 0 
                                ? 'Partial' 
                                : 'Pending';

                        // Notes handling
                        let notes = item.additional_notes 
                            ? frappe.utils.escape_html(item.additional_notes) 
                            : '';

                        let shortNotes = notes.length > 80 
                            ? notes.substring(0, 80) + '...' 
                            : notes;

                        return `
                        <tr style="border-bottom: 1px solid #f0f0f0;">
                            
                            <td style="padding: 10px 14px; font-size: 12px; color: #888; width: 30px;">
                                ${idx + 1}
                            </td>

                            <td style="padding: 10px 14px;">
                                <div style="font-size: 13px; font-weight: 500; color: #222;">
                                    ${item.item_name || ''}
                                </div>
                                <div style="font-size: 11px; color: #999; margin-top: 2px;">
                                    ${item.item_code || ''}
                                </div>
                            </td>

                            <td style="padding: 10px 14px; text-align: center;">
                                ${item.qty || 0} ${item.uom || ''}
                            </td>

                            <!-- NEW NOTES COLUMN -->
                            <td style="padding: 10px 14px; font-size: 12px; color: #555;">
                                ${notes ? `
                                    <div title="${notes}">
                                        ${shortNotes}
                                    </div>
                                ` : '-'}
                            </td>

                            <td style="padding: 10px 14px; text-align: center;">
                                <div style="font-size: 12px; color: #444; margin-bottom: 4px;">
                                    ${item.delivered_qty || 0} / ${item.qty || 0}
                                </div>
                                <div style="background: #eee; border-radius: 99px; height: 5px; width: 80px; margin: 0 auto;">
                                    <div style="background: ${barColor}; width: ${deliveredPct}%; height: 5px; border-radius: 99px;"></div>
                                </div>
                            </td>

                            <td style="padding: 10px 14px; text-align: center;">
                                <span style="
                                    font-size: 11px;
                                    font-weight: 500;
                                    color: ${statusColor};
                                    background: ${statusColor}18;
                                    padding: 3px 10px;
                                    border-radius: 99px;
                                ">
                                    ${statusLabel}
                                </span>
                            </td>

                        </tr>`;
                    }).join('');

                    let html = `
                    <div id="${safeId}" 
                         style="display:none; margin: 0; padding: 0 16px 12px 48px; background: #fafbfc; border-bottom: 2px solid #e8eaed;">
                        
                        <div style="background: #fff; border: 1px solid #e8eaed; border-radius: 8px; overflow: hidden; margin-top: 8px;">
                            
                            <table style="width: 100%; border-collapse: collapse;">
                                
                                <thead>
                                    <tr style="background: #f5f6f8; border-bottom: 1px solid #e8eaed;">
                                        <th style="padding: 8px 14px;">#</th>
                                        <th style="padding: 8px 14px;">Item</th>
                                        <th style="padding: 8px 14px; text-align:center;">Qty</th>
                                        <th style="padding: 8px 14px;">Notes</th> <!-- NEW -->
                                        <th style="padding: 8px 14px; text-align:center;">Delivered</th>
                                        <th style="padding: 8px 14px; text-align:center;">Status</th>
                                    </tr>
                                </thead>

                                <tbody>
                                    ${rows}
                                </tbody>

                            </table>

                        </div>
                    </div>`;

                    let $listItem = $(`[data-name="${doc.name}"]`).closest('.list-row-container');
                    if (!$listItem.length) $listItem = $(`[data-name="${doc.name}"]`).closest('.list-row');
                    if (!$listItem.length) $listItem = $(`[data-name="${doc.name}"]`);

                    $listItem.after(html);
                    $('#' + safeId).slideDown(200);
                }
            });
        }
    }
};

